package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lianxibu.site.domain.jobs.CollectorNodeFacts;import com.lianxibu.site.service.jobs.OperationalRuleEngine.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;
class CollectorNodeMonitoringCycleTest {
 static final String NODE="fictional-node";static final Key HEART=new Key("OPS-02","collector",NODE),DISK=new Key("OPS-05","collector",NODE);static final List<Key> KEYS=List.of(HEART,DISK);
 CollectorNodeFacts.Evidence evidence(OperationalPersistenceFixture f,long queue){return new CollectorNodeFacts.Evidence(NODE,1,true,f.clock.now.minusSeconds(1000),new CollectorNodeFacts.Heartbeat(1,1,f.clock.now,f.clock.now,0,0,0,queue,2L<<30,null),0,f.clock.now);}
 CollectorNodeMonitoringCycle cycle(OperationalPersistenceFixture f,CollectorNodeFacts.Api api){var store=f.store();var cycle=new CollectorNodeMonitoringCycle(NODE,KEYS,api,store,f.monitor(store),f.clock);cycle.start();return cycle;}
 @Test void oneActualAcquisitionFeedsTwoPermanentRulesAndRestartReadsNoProvider(){var f=new OperationalPersistenceFixture();var count=new AtomicInteger();CollectorNodeFacts.Api api=id->{assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());count.incrementAndGet();return evidence(f,384L<<20);};assertEquals(CollectorNodeMonitoringCycle.Outcome.SAMPLED,cycle(f,api).tick());assertEquals(Status.NORMAL,f.store().read(HEART).status());assertTrue(f.store().read(DISK).guards().contains(Guard.NEW_FETCH));assertEquals(CollectorNodeMonitoringCycle.Outcome.ALREADY_SAMPLED,cycle(f,api).tick());assertEquals(1,count.get());assertEquals(1,f.store().read(HEART).counters().get("heartbeats"));f.clock.now=f.clock.now.plusSeconds(60);cycle(f,id->{throw new IllegalStateException("fictional provider failure");}).tick();assertEquals(Status.TELEMETRY_UNKNOWN,f.store().read(HEART).status());assertEquals(Status.TELEMETRY_UNKNOWN,f.store().read(DISK).status());assertTrue(f.store().read(DISK).guards().contains(Guard.NEW_FETCH));assertEquals(1,f.store().read(DISK).counters().get("node_history"));}
 @Test void stoppedCrossMinuteOuterTransactionAndIncompletePairCannotWritePositiveState(){var f=new OperationalPersistenceFixture();var store=f.store();var stopped=new CollectorNodeMonitoringCycle(NODE,KEYS,id->{fail("default stopped must do no IO");return null;},store,f.monitor(store),f.clock);assertEquals(CollectorNodeMonitoringCycle.Outcome.STOPPED,stopped.tick());assertNull(store.read(HEART));cycle(f,id->{var e=evidence(f,0);f.clock.now=f.clock.now.plusSeconds(60);return e;}).tick();assertEquals(Status.TELEMETRY_UNKNOWN,store.read(HEART).status());assertEquals(Status.TELEMETRY_UNKNOWN,store.read(DISK).status());assertThrows(IllegalStateException.class,()->new org.springframework.transaction.support.TransactionTemplate(f.tx).execute(s->cycle(f,id->evidence(f,0)).tick()));assertThrows(IllegalArgumentException.class,()->new CollectorNodeMonitoringCycle(NODE,List.of(HEART),id->null,store,f.monitor(store),f.clock));}
 @Test void oneRuleWriteFailureDoesNotStarveTheOtherPermanentSample(){var f=new OperationalPersistenceFixture();var store=mock(OperationalMonitoringService.Store.class);var monitor=mock(OperationalMonitoringService.class);when(monitor.sample(eq(HEART),anyBoolean(),any(),any(),any())).thenThrow(new IllegalStateException("fictional write unavailable"));var cycle=new CollectorNodeMonitoringCycle(NODE,KEYS,id->evidence(f,0),store,monitor,f.clock);cycle.start();assertThrows(IllegalStateException.class,cycle::tick);verify(monitor).sample(eq(DISK),eq(true),any(CollectorNode.class),eq(f.clock.now),any());}
 @Test void singleFlightStopAndOriginalPartialMinuteNeverOverwriteACommittedRule()throws Exception{var f=new OperationalPersistenceFixture();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var cycle=cycle(f,id->{entered.countDown();try{assertTrue(release.await(5,TimeUnit.SECONDS));}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}return evidence(f,0);});var pool=Executors.newSingleThreadExecutor();try{var first=pool.submit(cycle::tick);assertTrue(entered.await(5,TimeUnit.SECONDS));assertEquals(CollectorNodeMonitoringCycle.Outcome.BUSY,cycle.tick());cycle.stop();release.countDown();assertEquals(CollectorNodeMonitoringCycle.Outcome.STOPPED,first.get(5,TimeUnit.SECONDS));assertNull(f.store().read(HEART));assertNull(f.store().read(DISK));}finally{release.countDown();pool.shutdownNow();}var store=f.store();var original=f.monitor(store).sample(HEART,true,new CollectorNode(evidence(f,0)),f.clock.now,new SharedWriteExecutor.ActionContext("fictional-heart-original","fictional-heart",null));cycle(f,id->evidence(f,384L<<20)).tick();assertEquals(original,f.store().read(HEART));assertTrue(f.store().read(DISK).guards().contains(Guard.NEW_FETCH));}
}
